export function portLabel(port) {
  if (!port) return "";
  return `${port.name} (${port.code}) - ${port.country}`;
}

export function getNextCustomerId() {
  return `CUS-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

export function getNextSupplierId() {
  return `SUP-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

export function getLocalTodayDateKey() {
  const today = new Date();
  const timezoneOffset = today.getTimezoneOffset() * 60 * 1000;
  return new Date(today.getTime() - timezoneOffset).toISOString().slice(0, 10);
}

